        if (*(char **)(data + 0x24) != 0) {
            qcopy(data + 0x10, *(char **)(data + 0x24) + 0x10);
        }
        MOBY(moby)->scale = *(float *)(((char *)MOBY(moby)->pclass) + 0x24) *
                            (firing_moby->scale / *(float *)(((char *)firing_moby->pclass) + 0x24));
